css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); display: grid; place-items: center; perspective: 600px; }
.loader .ring { position: relative; width: 70%; height: 70%; transform-style: preserve-3d; animation: carousel calc(var(--loader-speed) * 3) linear infinite; }
.loader .ring span { position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size) * .13); height: calc(var(--loader-size) * .13); margin: calc(var(--loader-size) * -.065) 0 0 calc(var(--loader-size) * -.065); border-radius: 50%; background: var(--accent); }
.loader .ring span:nth-child(even) { background: var(--accent-2); }
.loader .ring span:nth-child(1) { transform: rotateY(0deg) translateZ(calc(var(--loader-size) * .32)); }
.loader .ring span:nth-child(2) { transform: rotateY(45deg) translateZ(calc(var(--loader-size) * .32)); }
.loader .ring span:nth-child(3) { transform: rotateY(90deg) translateZ(calc(var(--loader-size) * .32)); }
.loader .ring span:nth-child(4) { transform: rotateY(135deg) translateZ(calc(var(--loader-size) * .32)); }
.loader .ring span:nth-child(5) { transform: rotateY(180deg) translateZ(calc(var(--loader-size) * .32)); }
.loader .ring span:nth-child(6) { transform: rotateY(225deg) translateZ(calc(var(--loader-size) * .32)); }
.loader .ring span:nth-child(7) { transform: rotateY(270deg) translateZ(calc(var(--loader-size) * .32)); }
.loader .ring span:nth-child(8) { transform: rotateY(315deg) translateZ(calc(var(--loader-size) * .32)); }
@keyframes carousel { to { transform: rotateY(360deg); } }
